#include <iostream>
#include <string>
using namespace std;

string findSaras(int n) {
    string places[] = {
        "You found Saras in the kitchen, haunted school, and music room",
        "You thought you found Saras for a second in the backyard, dog house, and well",
        "You sage the old house, the bathroom, and the garage",
        "You ran out of sage right after you went in the basement, panic room and attic"
    };

    if (n <= 3)
        return places[0];
    else if (n <= 6)
        return places[1];
    else if (n <= 9)
        return places[2];
    else
        return places[3];
}

int main() {
    int n;
    cin >> n;

    cout << findSaras(n);

    return 0;
}

